#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define RADIX 255
#define OFF1 5
#define OFF2 2
#define LITSIZE 4

int cc[1000000];
long long low = 0, range = 1;

void normalize() {
    while (range < RADIX) {
        int byte_out = (low / RADIX) + 1;
        if (byte_out > 255) byte_out = 255;
        fprintf(stderr, "NORM: output byte=%d, low=%lld, range=%lld\n", byte_out, low, range);
        putchar(byte_out);
        low = (low % RADIX) * RADIX;
        range *= RADIX;
    }
}

void put_bit(int bit, int ctx) {
    normalize();
    int *counts = &cc[ctx * 2];
    long long split = range * (counts[0] + 1) / (counts[0] + counts[1] + 2);
    fprintf(stderr, "PUT_BIT: bit=%d ctx=%d counts=[%d,%d] split=%lld range=%lld\n", 
            bit, ctx, counts[0], counts[1], split, range);
    if (bit) {
        low += split;
        range -= split;
        counts[1]++;
    } else {
        range = split;
        counts[0]++;
    }
}

void put_integer(int value, int off, int ctx) {
    fprintf(stderr, "PUT_INT: value=%d off=%d ctx=%d\n", value, off, ctx);
    int tmp = off;
    value += (1 << tmp);
    while (value >= (1 << (tmp + 1))) {
        put_bit(1, ctx * 99 + tmp + 1);
        tmp++;
    }
    put_bit(0, ctx * 99 + tmp + 1);
    while (tmp--) {
        put_bit((value >> tmp) & 1, ctx);
    }
}

void flush() {
    fprintf(stderr, "FLUSH: low=%lld\n", low);
    for (int i = 0; i < 10; i++) {
        int byte_out = (low / RADIX) + 1;
        if (byte_out > 255) byte_out = 255;
        fprintf(stderr, "FLUSH[%d]: byte=%d\n", i, byte_out);
        putchar(byte_out);
        low = (low % RADIX) * RADIX;
    }
}

int main() {
